import{_ as t,o as a,c as i,ag as n}from"./chunks/framework.B3IQijK_.js";const g=JSON.parse('{"title":"Connect TradingView","description":"Prepare TradingView Desktop for tradecli chart, market-data, Pine, and Strategy Lab workflows.","frontmatter":{"title":"Connect TradingView","description":"Prepare TradingView Desktop for tradecli chart, market-data, Pine, and Strategy Lab workflows.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/getting-started/tradingview-setup"}]]},"headers":[],"relativePath":"getting-started/tradingview-setup.md","filePath":"getting-started/tradingview-setup.md"}'),r={name:"getting-started/tradingview-setup.md"};function o(s,e,d,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="connect-tradingview" tabindex="-1">Connect TradingView <a class="header-anchor" href="#connect-tradingview" aria-label="Permalink to &quot;Connect TradingView&quot;">​</a></h1><p>tradecli uses TradingView Desktop for chart state, TradingView-derived prices, Pine compilation, and Strategy Lab simulation. TradingView is a connected system; the trading book, experiment plan, results, strategy versions, and paper ledger remain in tradecli&#39;s local Trading Office records.</p><p>This is separate from <a href="./browser-setup">Browser Setup</a>. Browser Setup prepares the Chrome profile used for web workflows. TradingView workflows connect to the locally running TradingView Desktop application.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>Confirm that:</p><ul><li><a href="https://www.tradingview.com/desktop/" target="_blank" rel="noreferrer">TradingView Desktop</a> is installed;</li><li>you can sign in and open a chart in the Desktop application;</li><li><code>tradecli setup</code> has completed; and</li><li><code>tradecli doctor</code> reports the TradingView MCP source package as cached.</li></ul><p><code>tradecli setup</code> downloads the TradingView connector used by tradecli. It does not install the TradingView Desktop application or sign in to your TradingView account.</p><h2 id="connect-the-desktop-application" tabindex="-1">Connect the Desktop application <a class="header-anchor" href="#connect-the-desktop-application" aria-label="Permalink to &quot;Connect the Desktop application&quot;">​</a></h2><ol><li>Open TradingView Desktop once, sign in, and open or create a chart layout.</li><li>Launch <code>tradecli</code> and enter the Trader or Trading Office workflow that needs TradingView.</li><li>Ask the active employee:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check the TradingView connection. If it is not connected, launch TradingView</span></span>
<span class="line"><span>without closing an existing instance. Then tell me which symbol and timeframe</span></span>
<span class="line"><span>are open.</span></span></code></pre></div><p>tradecli checks the local TradingView connection before using chart, Pine, or market-data tools. A successful check returns the connected chart context, including its current symbol and timeframe.</p><p>If the Desktop application is open but the connection is unavailable, ask tradecli to launch TradingView without closing the existing application. Restarting an existing TradingView instance is a separate recovery action and should not happen without your approval.</p><h2 id="prepare-strategy-lab" tabindex="-1">Prepare Strategy Lab <a class="header-anchor" href="#prepare-strategy-lab" aria-label="Permalink to &quot;Prepare Strategy Lab&quot;">​</a></h2><p>Strategy Lab uses TradingView as its simulation target. Before starting <a href="/trading-sandbox-website-preview/wiki/trading-office/quickstart">Your First Strategy</a>:</p><ol><li>Keep TradingView Desktop open.</li><li>Confirm that the connection check succeeds.</li><li>Open a normal chart for the market you intend to test.</li></ol><p>During BUILD, tradecli writes or restores a Pine strategy and compiles it on the chart. The first build can expose a manual <strong>Add to chart</strong> step. After that action, the build gate checks the compiled strategy and its declared inputs before PLAN can continue.</p><h2 id="what-the-connection-is-used-for" tabindex="-1">What the connection is used for <a class="header-anchor" href="#what-the-connection-is-used-for" aria-label="Permalink to &quot;What the connection is used for&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>TradingView provides</th></tr></thead><tbody><tr><td>Chart research</td><td>Symbol, timeframe, bars, indicators, drawings, and screenshots</td></tr><tr><td>Strategy Lab</td><td>Pine compilation and backtest simulation</td></tr><tr><td>Paper planning</td><td>TradingView-derived prices when the paper fill is not supplied explicitly</td></tr><tr><td>Position monitoring</td><td>Current marks used to evaluate recorded paper exit rules</td></tr></tbody></table><p>TradingView does not hold the Trading Office book, approvals, paper ledger, strategy lineage, journal, or reviews. It also does not turn an Office paper trade into a broker order.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="the-connector-package-is-missing" tabindex="-1">The connector package is missing <a class="header-anchor" href="#the-connector-package-is-missing" aria-label="Permalink to &quot;The connector package is missing&quot;">​</a></h3><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tradecli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tradecli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span></span></code></pre></div><p>The fix path can refresh a missing or stale TradingView connector package.</p><h3 id="tradingview-desktop-is-open-but-not-connected" tabindex="-1">TradingView Desktop is open but not connected <a class="header-anchor" href="#tradingview-desktop-is-open-but-not-connected" aria-label="Permalink to &quot;TradingView Desktop is open but not connected&quot;">​</a></h3><ul><li>Ask tradecli to run the TradingView connection check again.</li><li>If needed, ask it to launch TradingView without closing the existing instance.</li><li>Close and restart TradingView only when the non-destructive launch path does not restore the connection and you are ready to interrupt the current Desktop session.</li></ul><h3 id="a-backtest-pauses-after-a-connection-failure" tabindex="-1">A backtest pauses after a connection failure <a class="header-anchor" href="#a-backtest-pauses-after-a-connection-failure" aria-label="Permalink to &quot;A backtest pauses after a connection failure&quot;">​</a></h3><p>Completed chunks remain stored. The Strategy Lab workflow retries temporary TradingView failures with backoff. Use <strong>Backtest Lab → Jobs → Status</strong> to inspect the saved job rather than starting a duplicate experiment.</p><h3 id="build-stops-at-the-chart" tabindex="-1">BUILD stops at the chart <a class="header-anchor" href="#build-stops-at-the-chart" aria-label="Permalink to &quot;BUILD stops at the chart&quot;">​</a></h3><p>Check the TradingView window for the Pine strategy and complete the manual <strong>Add to chart</strong> action when it appears. Strategy Lab verifies the compiled strategy again before it accepts the build.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/trading-sandbox-website-preview/wiki/trading-office/setup">Set up your Trading Office</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/quickstart">Your first strategy</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/strategy-lab">Test in Strategy Lab</a></li><li><a href="./browser-setup">Browser Setup</a></li></ul>`,32)])])}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
